The files need to define the `grade_school::school` class with methods to add students, retrieve a grade, and retrieve the complete sorted roster. A `std::map` keeps grades ordered, while `std::set` keeps student names alphabetically sorted and prevents duplicates. Duplicate additions are ignored because the standard API uses a `void` return type.

grade_school.h
```cpp
#if !defined(GRADE_SCHOOL_H)
#define GRADE_SCHOOL_H

#include <map>
#include <set>
#include <string>
#include <vector>

namespace grade_school {

class school {
public:
    void add(const std::string& student, int grade);
    std::vector<std::string> grade(int grade) const;
    std::vector<std::string> roster() const;

private:
    std::map<int, std::set<std::string>> students_by_grade;
    std::set<std::string> students;
};

}  // namespace grade_school

#endif // GRADE_SCHOOL_H
```

grade_school.cpp
```cpp
#include "grade_school.h"

namespace grade_school {

void school::add(const std::string& student, int grade)
{
    if (!students.insert(student).second) {
        return;
    }

    students_by_grade[grade].insert(student);
}

std::vector<std::string> school::grade(int grade) const
{
    std::vector<std::string> result;

    const auto it = students_by_grade.find(grade);
    if (it == students_by_grade.end()) {
        return result;
    }

    result.assign(it->second.begin(), it->second.end());
    return result;
}

std::vector<std::string> school::roster() const
{
    std::vector<std::string> result;

    for (const auto& [grade_number, students_in_grade] : students_by_grade) {
        result.insert(
            result.end(),
            students_in_grade.begin(),
            students_in_grade.end());
    }

    return result;
}

}  // namespace grade_school
